package net.flovex.core.integration;
import net.flovex.core.FlovexCore;import me.clip.placeholderapi.expansion.PlaceholderExpansion;import org.bukkit.Bukkit;import org.bukkit.OfflinePlayer;import org.bukkit.entity.Player;import java.util.*;
public final class FlovexExpansion extends PlaceholderExpansion{
 private final FlovexCore plugin;public FlovexExpansion(FlovexCore p){plugin=p;}
 @Override public String getIdentifier(){return "flovexcore";}@Override public String getAuthor(){return "Flovex";}@Override public String getVersion(){return plugin.getDescription().getVersion();}@Override public boolean persist(){return true;}
 @Override public String onRequest(OfflinePlayer player,String params){if(player==null)return "";UUID id=player.getUniqueId();var stats=plugin.getStorage().rows("SELECT kills,deaths,blocks_broken,blocks_placed FROM player_stats WHERE uuid=?",id.toString());var row=stats.isEmpty()?Map.<String,Object>of():stats.getFirst();return switch(params.toLowerCase(Locale.ROOT)){case "kills"->String.valueOf(row.getOrDefault("kills",0));case "deaths"->String.valueOf(row.getOrDefault("deaths",0));case "blocks_broken"->String.valueOf(row.getOrDefault("blocks_broken",0));case "blocks_placed"->String.valueOf(row.getOrDefault("blocks_placed",0));case "playtime"->{var r=plugin.getStorage().rows("SELECT play_ticks FROM player_data WHERE uuid=?",id.toString());yield r.isEmpty()?"0":String.valueOf(((Number)r.getFirst().get("play_ticks")).longValue()/72000);}case "team"->{var r=plugin.getStorage().rows("SELECT t.name FROM teams t JOIN team_members m ON m.team_id=t.id WHERE m.uuid=?",id.toString());yield r.isEmpty()?"None":String.valueOf(r.getFirst().get("name"));}case "ffa_rating"->{var r=plugin.getStorage().rows("SELECT rating FROM ffa_stats WHERE uuid=?",id.toString());yield r.isEmpty()?"1000":String.valueOf(r.getFirst().get("rating"));}case "ping"->{Player p=player.getPlayer();yield p==null?"-1":String.valueOf(p.getPing());}case "platform"->{Player p=player.getPlayer();yield p==null?"offline":plugin.getPlatform().isBedrock(p)?"bedrock":"java";}default->null;};}
}